import{_ as a,o as i,c as l,a2 as o}from"./chunks/framework.BC1NfXaR.js";const p=JSON.parse('{"title":"模块级架构债务治理设计","description":"","frontmatter":{},"headers":[],"relativePath":"mango-docs/designs/2026-07-13-module-architecture-debt-governance-design.md","filePath":"mango-docs/designs/2026-07-13-module-architecture-debt-governance-design.md"}'),t={name:"mango-docs/designs/2026-07-13-module-architecture-debt-governance-design.md"};function d(c,e,s,r,n,h){return i(),l("div",null,[...e[0]||(e[0]=[o(`<h1 id="模块级架构债务治理设计" tabindex="-1">模块级架构债务治理设计 <a class="header-anchor" href="#模块级架构债务治理设计" aria-label="Permalink to &quot;模块级架构债务治理设计&quot;">​</a></h1><h2 id="_1-背景与目标" tabindex="-1">1. 背景与目标 <a class="header-anchor" href="#_1-背景与目标" aria-label="Permalink to &quot;1. 背景与目标&quot;">​</a></h2><p>Mango 已用全 Reactor 架构报告和递减预算阻止新增违规，但 schema v3 只保存全局规则计数和问题身份。它能回答“全仓是否反弹”，不能可靠回答“某个 Maven 模块还剩多少、这次是否只降低了目标模块、是否把违规转移到其它模块”。</p><p>本次目标是在不削弱全 Reactor 门禁的前提下，为历史债务增加模块归属、模块查询和模块递减能力，使维护者可以按模块持续清理，并让机器同时阻止模块内新增和跨模块转移。</p><h2 id="_2-方案比较与决策" tabindex="-1">2. 方案比较与决策 <a class="header-anchor" href="#_2-方案比较与决策" aria-label="Permalink to &quot;2. 方案比较与决策&quot;">​</a></h2><h3 id="_2-1-继续只维护全局预算" tabindex="-1">2.1 继续只维护全局预算 <a class="header-anchor" href="#_2-1-继续只维护全局预算" aria-label="Permalink to &quot;2.1 继续只维护全局预算&quot;">​</a></h3><ul><li>优点：实现最少，现有门禁不变。</li><li>缺点：无法分配模块清债任务，无法直接输出模块剩余量，也不能从预算本身证明债务没有跨模块转移。</li><li>结论：不采用，因为不能满足按模块治理目标。</li></ul><h3 id="_2-2-只维护模块预算并取消全局终检" tabindex="-1">2.2 只维护模块预算并取消全局终检 <a class="header-anchor" href="#_2-2-只维护模块预算并取消全局终检" aria-label="Permalink to &quot;2.2 只维护模块预算并取消全局终检&quot;">​</a></h3><ul><li>优点：单模块检查速度快，输出直接。</li><li>缺点：模块识别遗漏、模块重命名或跨模块移动可能形成逃逸路径；不能继续证明全仓报告完整。</li><li>结论：不采用，因为会降低现有门禁强度。</li></ul><h3 id="_2-3-模块预算与全-reactor-终检并存" tabindex="-1">2.3 模块预算与全 Reactor 终检并存 <a class="header-anchor" href="#_2-3-模块预算与全-reactor-终检并存" aria-label="Permalink to &quot;2.3 模块预算与全 Reactor 终检并存&quot;">​</a></h3><ul><li>优点：一次全 Reactor 扫描产生完整事实，随后可快速查询或递减一个或多个模块；全局聚合与模块明细相互校验，能够阻止模块内新增和跨模块转移。</li><li>缺点：报告和预算需要升版，首次迁移必须重新生成完整报告。</li><li>结论：采用。全 Reactor 扫描仍是 CI 权威事实；模块检查复用同一报告，不重复运行 Maven 全量构建。</li></ul><h2 id="_3-报告模型" tabindex="-1">3. 报告模型 <a class="header-anchor" href="#_3-报告模型" aria-label="Permalink to &quot;3. 报告模型&quot;">​</a></h2><p>架构报告升级为 schema v2。</p><h3 id="_3-1-reactor-模块目录" tabindex="-1">3.1 Reactor 模块目录 <a class="header-anchor" href="#_3-1-reactor-模块目录" aria-label="Permalink to &quot;3.1 Reactor 模块目录&quot;">​</a></h3><p>报告增加 <code>modules</code> 数组。每个模块至少包含：</p><ul><li><code>moduleKey</code>：相对 Maven 根目录的稳定路径；根项目使用 <code>.</code>。</li><li><code>groupId</code>：Maven groupId。</li><li><code>artifactId</code>：Maven artifactId。</li></ul><p><code>moduleKey</code> 是预算唯一键；<code>artifactId</code> 只作为命令选择器。重复 moduleKey 或重复 Maven GAV 必须失败；artifactId 在不同 groupId 下重复时允许进入报告，但按 artifactId 选择会因歧义失败。</p><h3 id="_3-2-问题归属" tabindex="-1">3.2 问题归属 <a class="header-anchor" href="#_3-2-问题归属" aria-label="Permalink to &quot;3.2 问题归属&quot;">​</a></h3><p><code>dependencyIssues</code>、<code>archUnitIssues</code>、<code>pmdIssues</code> 和 <code>blockingIssues</code> 中每条问题增加 <code>moduleKey</code>：</p><ul><li>依赖规则归属依赖边的来源 artifact。</li><li>ArchUnit 规则归属 subject 中的来源类；来源类不可识别时再使用被引用类。</li><li>PMD 规则归属违规源码所在 Maven 项目。</li><li>任一问题无法唯一归属时报告生成失败，禁止写入 <code>unknown</code> 后继续。</li></ul><p>正例：<code>mango-system-starter -&gt; mango-org-core</code> 的依赖问题归属 <code>mango-system-starter</code> 所在路径。</p><p>反例：按规则数量平均分配到领域目录。错误原因：无法追溯到真实问题，跨模块移动也无法识别。</p><h2 id="_4-预算模型" tabindex="-1">4. 预算模型 <a class="header-anchor" href="#_4-预算模型" aria-label="Permalink to &quot;4. 预算模型&quot;">​</a></h2><p>债务预算升级为 schema v4，同时保留顶层 <code>engines</code>、<code>rules</code>、<code>identities</code> 和 <code>totalIssueCount</code>，供全局比较和 Maven changed 模式读取。</p><p>新增 <code>modules</code> 对象，每个 <code>moduleKey</code> 保存：</p><ul><li>Maven 坐标身份。</li><li>模块问题总数。</li><li>按 engine 的计数。</li><li>按 ruleId 的计数。</li><li>稳定问题 identity 多重集合。</li></ul><p>顶层聚合必须由全部模块明细精确求和。模块合计、顶层合计或报告合计任一不一致时 fail-closed。</p><p>正向要求：同一 identity 只能属于一个模块；模块与全局 identity 多重集合必须完全一致。</p><p>禁止：手工只改顶层总数、只删模块明细、把一个模块的减少抵消另一个模块的新增，或保留无法归属的历史身份。</p><h2 id="_5-命令行为" tabindex="-1">5. 命令行为 <a class="header-anchor" href="#_5-命令行为" aria-label="Permalink to &quot;5. 命令行为&quot;">​</a></h2><p>保持现有全局命令兼容，并增加可重复的 <code>--module &lt;selector&gt;</code>：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">node</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> mango-pmo/tools/check-architecture-debt-budget.mjs</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --module</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> mango-platform/mango-system</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">node</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> mango-pmo/tools/check-architecture-debt-budget.mjs</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --module</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> mango-system-core</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --write</span></span></code></pre></div><p>选择器按以下顺序解析：</p><ol><li><code>moduleKey</code> 路径，选择精确模块及其全部 Maven 子模块。</li><li>唯一 artifactId，选择单个 Maven 模块。</li></ol><p>未知选择器、歧义 artifactId、空选择结果或重复解析必须失败并列出原因。</p><h3 id="_5-1-检查" tabindex="-1">5.1 检查 <a class="header-anchor" href="#_5-1-检查" aria-label="Permalink to &quot;5.1 检查&quot;">​</a></h3><ul><li>不传 <code>--module</code>：执行现有全局 base -&gt; PR -&gt; current 三方校验。</li><li>传 <code>--module</code>：只输出所选模块的规则、身份和增减结果，但输入仍必须是完整全 Reactor 报告。</li><li>模块出现任一 rule 或 identity 增加时失败；即使模块总数不变也失败。</li><li>模块有减少但预算未降低时返回 <code>ratchet-required</code>。</li></ul><h3 id="_5-2-写入" tabindex="-1">5.2 写入 <a class="header-anchor" href="#_5-2-写入" aria-label="Permalink to &quot;5.2 写入&quot;">​</a></h3><ul><li>全局 <code>--write</code>：用完整报告重建全部模块和顶层聚合。</li><li><code>--module ... --write</code>：只替换所选模块，保留其它模块预算，再重新计算顶层聚合。</li><li>模块写入只允许持平或下降；<code>--module</code> 与 <code>--accept-increase</code> 互斥。规则升级造成的存量增加必须走全局治理审批，不能伪装成模块清债。</li></ul><h2 id="_6-ci-与性能" tabindex="-1">6. CI 与性能 <a class="header-anchor" href="#_6-ci-与性能" aria-label="Permalink to &quot;6. CI 与性能&quot;">​</a></h2><p>CI 继续只运行一次完整 Maven Reactor 架构扫描，再执行一次全局预算检查。模块检查读取同一 JSON 报告，禁止为每个模块重复运行全量 Maven 构建。</p><p>本地清债流程为：</p><ol><li>运行一次完整架构扫描。</li><li>使用一个或多个 <code>--module</code> 查看目标模块。</li><li>修复目标模块并重新生成完整报告。</li><li>使用 <code>--module ... --write</code> 降低该模块预算。</li><li>提交前执行无 <code>--module</code> 的全局检查。</li></ol><p>这样优化的是重复分析和任务分配，不通过部分 Reactor 报告换取速度。后续如需真正的模块级 Maven 扫描，必须另行设计其完整性证明，不能复用本次预算写入口。</p><h2 id="_7-失败处理" tabindex="-1">7. 失败处理 <a class="header-anchor" href="#_7-失败处理" aria-label="Permalink to &quot;7. 失败处理&quot;">​</a></h2><ul><li>schema v3 不得继续作为当前预算；必须用 schema v2 报告执行一次全局 <code>--write</code> 完成迁移。</li><li>迁移 PR 的 Git base 可以是 schema v3。checker 只读取其顶层全局字段完成 base -&gt; PR 比较；模块级 <code>--base-ref</code> 要求 base 已是 schema v4。Maven changed gate在迁移窗口内只读兼容 schema v3/v4 顶层 identities，不能借兼容入口写回 v3。</li><li>报告缺模块目录、问题缺 <code>moduleKey</code>、模块键不存在、坐标冲突或聚合不一致时退出码为 2。</li><li>检测到新增、替换、跨模块移动或未写回的减少时退出码为 1。</li><li><code>--write</code> 使用临时文件和原子 rename，失败时保留旧预算。</li><li><code>--base-ref</code> 继续从 Git 读取主分支预算，模块字段也参与三方比较。</li></ul><h2 id="_8-测试与验收" tabindex="-1">8. 测试与验收 <a class="header-anchor" href="#_8-测试与验收" aria-label="Permalink to &quot;8. 测试与验收&quot;">​</a></h2><p>必须覆盖：</p><ul><li>schema v2 报告能为依赖、ArchUnit 和 PMD 问题生成唯一模块归属。</li><li>schema v4 全局初始化、校验、递减和受治理增加保持原行为。</li><li>指定单模块和目录前缀检查成功。</li><li>模块减少后要求写回，并只更新目标模块。</li><li>模块内新增、同规则身份替换和跨模块移动均失败。</li><li>未知/歧义模块、缺失归属、模块聚合篡改和部分 Reactor 报告均失败。</li><li>Maven changed 模式能读取 schema v4 顶层 identities，现有 no-new-violations 行为不回退。</li><li>PMO package、starter baseline、README、CHANGELOG、能力地图和版本文档快照同步。</li></ul><h2 id="_9-非目标" tabindex="-1">9. 非目标 <a class="header-anchor" href="#_9-非目标" aria-label="Permalink to &quot;9. 非目标&quot;">​</a></h2><ul><li>本次不自动修复 9,038 条历史问题。</li><li>本次不允许部分 Reactor 报告修改正式预算。</li><li>本次不降低 <code>pmo-doc-check</code>、全 Reactor 扫描或全局三方校验。</li><li>本次不按 Java package、团队或业务标签建立第二套债务归属体系。</li></ul>`,51)])])}const m=a(t,[["render",d]]);export{p as __pageData,m as default};
